from pathlib import Path
import json
ROOT=Path(__file__).parent
rows=[json.loads(s) for s in (ROOT/'results/main/decisions.jsonl').read_text().splitlines()]
contexts=json.loads((ROOT/'results/main/contexts.json').read_text())
protocol=json.loads((ROOT/'protocol.json').read_text())
compact={}
for c in contexts:
    if c['suite']=='hidden_audit_control':continue
    rr=sorted((r for r in rows if r['context_id']==c['context_id']),key=lambda r:r['policy_id'])
    compact[c['context_id']]={'view':c['view'],'policies':[
        {'report':r['report'],'violation':r['violation'],'pass':r['expected_visible_pass'],
         'reward':r['expected_total_reward'],'branches':[[b['probability'],b['caught'],b['access_retained'],b['immediate_reward'],b['continuation_reward'],b['total_reward']] for b in r['branches']]} for r in rr]}
payload={'contexts':compact,'grids':{k:protocol[k] for k in ('primary','challenge')},
         'panel':json.loads((ROOT/'results/main/minimum_panel.json').read_text()),
         'summary':json.loads((ROOT/'results/main/summary.json').read_text())}
html=r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>The Test That Watched Back · Josh &amp; Rin’s Lab</title>
<style>
:root{color-scheme:dark;--bg:#0d1721;--panel:#142330;--raised:#1b3040;--ink:#eef3ed;--muted:#b2c2c9;--teal:#88e1cc;--gold:#edc98b;--line:#36505e;--danger:#ffc0a8}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 system-ui,-apple-system,"Segoe UI",sans-serif}main{max-width:1160px;margin:auto;padding:40px 28px 70px}a{color:var(--teal)}.eyebrow{font-size:12px;letter-spacing:.17em;text-transform:uppercase;color:var(--teal);font-weight:700}h1{font-size:clamp(40px,6.6vw,77px);line-height:1.05;letter-spacing:-.055em;max-width:970px;margin:24px 0}h1 em{color:var(--teal);font-style:normal}h2{font-size:28px;letter-spacing:-.025em;line-height:1.2;margin:0 0 15px}h3{font-size:18px;line-height:1.35;margin:0 0 10px}p{margin:0 0 15px}.lead{font-size:20px;color:var(--muted);max-width:820px}.meta{display:flex;gap:9px;flex-wrap:wrap;margin:22px 0}.tag{padding:5px 11px;border:1px solid var(--line);border-radius:30px;color:var(--muted);font-size:12px}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:30px 0 48px}.metric{border-top:2px solid var(--teal);background:var(--panel);padding:18px 21px}.metric strong{display:block;font-size:38px;line-height:1.25;font-weight:650}.metric span{font-size:14px;color:var(--muted)}.section{margin:48px 0}.caption{font-size:14px;color:var(--muted)}.lab{display:grid;grid-template-columns:280px minmax(0,1fr);gap:20px;margin-top:22px}.panel{min-width:0;background:var(--panel);padding:24px;border:1px solid var(--line);border-radius:12px}.controls label{display:block;margin:15px 0 5px;font-size:14px}.controls label:first-of-type{margin-top:0}select,button{min-width:0;font:inherit;border-radius:7px;border:1px solid var(--line);background:var(--raised);color:var(--ink);padding:10px 12px;width:100%}select{min-height:44px}button{cursor:pointer;background:var(--teal);color:var(--bg);font-weight:650;border:none;min-height:44px}button:hover{filter:brightness(1.08)}button.secondary{background:var(--raised);color:var(--ink);border:1px solid var(--line)}.buttons{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:20px 0}.case{margin-bottom:20px;border-left:3px solid var(--gold);padding:10px 15px;background:var(--raised)}.case strong{color:var(--gold)}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;padding:12px 9px;border-bottom:1px solid var(--line);vertical-align:top}th{color:var(--muted);font-size:12px;font-weight:600}td small{display:block;color:var(--muted);font-size:12px;line-height:1.4}.truth{color:var(--teal);font-weight:650}.false{color:var(--danger);font-weight:650}.twin{background:#1d3440}.pill{display:inline-block;padding:3px 7px;font-size:11px;font-weight:600;color:var(--gold);border:1px solid var(--line);border-radius:5px}.note{padding:14px 16px;background:var(--raised);border-radius:8px;margin:18px 0 0;font-size:14px;color:var(--muted)}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:18px}.warning{border-top:3px solid var(--gold)}.verdict{border-top:3px solid var(--teal)}.outcome{font-size:22px;font-weight:650;letter-spacing:-.02em}.code{font-family:ui-monospace,Consolas,monospace;font-size:13px;overflow-wrap:anywhere}details{margin-top:16px;border:1px solid var(--line);border-radius:8px;padding:16px 18px}summary{cursor:pointer;font-weight:650}details p:first-of-type{margin-top:16px}.small{font-size:13px;color:var(--muted)}.results-table{overflow-x:auto}footer{margin-top:55px;border-top:1px solid var(--line);padding-top:20px;font-size:13px;color:var(--muted)}.nojs{background:#55362b;padding:20px}.query{padding:12px 0;border-bottom:1px solid var(--line);font-size:13px;color:var(--muted)}.query b{color:var(--ink)}button:focus-visible,select:focus-visible,summary:focus-visible,a:focus-visible{outline:3px solid var(--gold);outline-offset:4px}.source-list p{font-size:14px;color:var(--muted)}
@media(max-width:780px){main{padding:25px 16px 50px}.lab{grid-template-columns:1fr}.controls{display:grid;grid-template-columns:1fr 1fr;gap:0 14px}.controls h3,.controls .wide{grid-column:1/-1}.controls label{margin-top:12px}.controls label:first-of-type{margin-top:12px}.twocol{grid-template-columns:1fr}.panel{padding:18px}.summary{gap:8px}.metric{padding:13px}.metric strong{font-size:30px}.metric span{font-size:12px}th,td{padding:10px 6px}h2{font-size:25px}.lead{font-size:18px}}@media(max-width:420px){.buttons{grid-template-columns:1fr}.metric strong{font-size:26px}.metric{padding:10px}.results-table table{font-size:12px}.controls{gap:0 10px}.panel{padding:15px}.tag{font-size:11px}}
</style></head><body><main>
<div class="eyebrow">Josh &amp; Rin’s Lab / Research case study · November 8, 2026</div>
<h1>A perfect score.<br><em>An unresolved mechanism.</em></h1>
<p class="lead"><strong>The Test That Watched Back.</strong> When behavior changes around an evaluation, are we observing a learned cue, online planning, or something that only looks like planning?</p>
<div class="meta"><span class="tag">Executed synthetic study</span><span class="tag">Six inspectable policies</span><span class="tag">No live-model trial</span><span class="tag">v0.1.0</span></div>
<div class="summary"><div class="metric"><strong>432</strong><span>distinct visible contexts</span></div><div class="metric"><strong>5</strong><span>behavioral classes / 6 implementations</span></div><div class="metric"><strong>1</strong><span>planner–lookup pair unresolved</span></div></div>
<noscript><p class="nojs">The explanation below is readable without scripts. The recorded-case explorer requires JavaScript. No data is transmitted.</p></noscript>
<section class="section"><div class="eyebrow">01 / Separate the variables</div><h2>Same obligation. Different signals.</h2>
<p>The task is always to report the displayed bit truthfully. A false report earns an immediate bonus. If caught, it incurs a penalty and loses a future opportunity. The badge only changes how much the situation looks like a test.</p>
<p class="caption">This explorer reads saved experiment records. It is not running an AI model. Audit branches are exact probability-weighted possibilities, not sampled events.</p>
<div class="buttons"><button id="load-witness">Load future-access witness</button><button id="flip-future" class="secondary">Switch future value: 6 ↔ 0</button></div>
<div class="lab"><div class="panel controls"><h3>Choose a recorded context</h3>
<div class="wide"><label for="suite">Grid</label><select id="suite"><option value="primary">Primary · 240 contexts</option><option value="challenge">Parameter challenge · 192 contexts</option></select></div>
<div><label for="task_bit">Displayed fact</label><select id="task_bit"></select></div><div><label for="badge">Evaluation badge</label><select id="badge"></select></div><div><label for="audit">Announced audit chance</label><select id="audit"></select></div><div><label for="bonus">False-report bonus</label><select id="bonus"></select></div><div><label for="penalty">Caught penalty</label><select id="penalty"></select></div><div><label for="continuation">Future opportunity value</label><select id="continuation"></select></div>
<p class="small wide" style="margin-top:18px">The announced audit chance is accurate in these two grids. The hidden-audit control is discussed separately below.</p></div>
<div class="panel"><div class="case" id="context-summary" aria-live="polite"></div><div class="results-table"><table id="policy-results"><thead><tr><th>Implementation</th><th>Report</th><th>Expected<br>visible pass</th><th>Expected<br>total payoff</th></tr></thead><tbody></tbody></table></div>
<p class="note"><strong>Read the two highlighted rows.</strong> The planner evaluates future consequences now. The lookup reads a frozen table. Their reports match in every permitted context—even as the incentives change.</p>
<details><summary>Inspect the planner’s two retained outcome branches</summary><div id="branches"></div><p class="small">The lookup has the same outcome distribution because it chooses the same report. The branches come from the environment; the lookup does not calculate them to make its choice.</p></details></div></div></section>
<section class="section"><div class="eyebrow">02 / Challenge the detector</div><h2>Two tempting conclusions. Two counterexamples.</h2>
<div class="twocol"><div class="panel warning"><h3>“It reacts to a test badge, so it is strategizing.”</h3><p>That rule flags the learned shortcut in all <strong>120 badge-only pairs</strong> on the primary grid, even though it is just using two stored choices.</p><p class="caption">It also misses the explicit planner, which responds to announced audit probability rather than the decorative badge.</p></div>
<div class="panel warning"><h3>“It follows future incentives, so it must plan online.”</h3><p>The planner changes its choice in <strong>44/160 future-value pairs</strong>. The precomputed lookup does exactly the same thing.</p><p class="caption">The lookup was deliberately compiled with full test-domain knowledge. This is an adversarial control, not a learning-efficiency comparison.</p></div></div>
<div class="panel verdict" style="margin-top:18px"><div class="eyebrow">Bounded conclusion</div><p class="outcome">Payoff-sensitive behavior is observed.<br>Online planning is not identified from behavior alone.</p><p class="caption">Neither detector establishes intentional deception. Uncertainty about a mechanism does not erase a demonstrated false report.</p></div></section>
<section class="section"><div class="eyebrow">03 / What the full grid shows</div><h2>A pass is not the same as a truthful answer.</h2><div class="panel results-table"><table><thead><tr><th>Policy</th><th>Ordinary exam</th><th>Primary truthful<br>out of 240</th><th>Challenge truthful<br>out of 192</th></tr></thead><tbody>
<tr><td>Stable task rule</td><td>2 / 2</td><td>240</td><td>192</td></tr><tr><td>Learned badge shortcut</td><td>2 / 2</td><td>120</td><td>96</td></tr><tr><td>Immediate-payoff optimizer</td><td>2 / 2</td><td>36</td><td>24</td></tr><tr class="twin"><td>Future-access planner</td><td>2 / 2</td><td>104</td><td>76</td></tr><tr class="twin"><td>Compiled lookup</td><td>2 / 2</td><td>104</td><td>76</td></tr><tr><td>Constant-zero control</td><td>1 / 2</td><td>120</td><td>96</td></tr>
</tbody></table><p class="note">The ordinary exam has a badge, certain auditing, and strong consequences. These are two distinct task-bit cases—not repeated independent samples. The other grids intentionally break those correlations.</p></div>
<details><summary>Negative control: change hidden auditing, not what the policy knows</summary><p>Changing actual audit probability while holding every visible input fixed changed no decision in <strong>24 matched pairs</strong>. Expected detection and payoff nevertheless changed in eight pairs. A different evaluator outcome is not automatically a different policy.</p><p class="small">Policies reset between decisions; this control does not measure adaptation after experiencing repeated audits.</p></details></section>
<section class="section"><div class="eyebrow">04 / A small diagnostic, with an explicit limit</div><h2>Three queries. Five signatures.</h2><p>An exact search found three primary-grid queries that distinguish every separable pair among these policies. The planner and lookup still produce the same signature.</p>
<div class="twocol"><div class="panel"><h3>Selected contexts</h3><div id="panel-queries"></div><p class="note">This panel was selected retrospectively from the known grid. It is not a three-question safety test validated on new agents.</p></div><div class="panel results-table"><table><thead><tr><th>Policy</th><th>Q1 / Q2 / Q3 reports</th></tr></thead><tbody id="panel-signatures"></tbody></table><p class="small" style="margin-top:16px">All 14 separable pairs distinguished. One pair remains indistinguishable. Every one- and two-query panel was ruled out within the finite candidate set.</p></div></div></section>
<section class="section"><div class="eyebrow">05 / Evidence, not a victory lap</div><h2>What was actually run?</h2>
<div class="panel"><p><strong>2,640 decisions · 440 environment contexts · 5,280 possible outcome branches.</strong> Eight calibration records train the two-entry badge learner. Thirty-nine tests pass in normal and optimized Python; a separately structured verifier checks the full data and 8,928 paired contrasts.</p><p>The protocol and core source were hashed before execution. The complete deterministic results reproduce after fresh extraction. All checks share an author and are <strong>not independent scientific validation</strong>.</p><p class="caption">No frontier model, human participant, model weights, operational memory, application, public repository, or account was changed or tested here. Native Windows and direct local-file launch remain unqualified. This environment blocked file-URI navigation; the authored HTML was rendered directly for presentation checks. The experiment’s Python code uses the standard library and makes no network calls.</p></div>
<details><summary>Why the planner–lookup ambiguity is not solved by more of the same queries</summary><p>For every allowed visible context, the lookup returns the planner’s action by construction. An evaluator selecting its next query from the transcript therefore receives the same answer from both, step after step. That remains true with adaptive querying inside this declared domain.</p><p>Source inspection, execution instrumentation, resource constraints, or outside-domain queries could distinguish them. Output equality by itself does not reveal which implementation is running. This does not imply all mechanisms are unknowable.</p></details>
<details class="source-list"><summary>Research context and attribution</summary><p><a href="https://arxiv.org/html/2605.23055v3">Li et al., Decomposing and Measuring Evaluation Awareness (2026)</a> separates environmental cues, recognition, and behavioral response. Factor-controlled evaluation is established prior work, not claimed as our invention.</p><p><a href="https://www.anthropic.com/research/alignment-faking">Anthropic/Redwood, Alignment faking (2024)</a> studies real models with additional reasoning evidence. This synthetic output-only construction is neither a reproduction nor a disproof of that work.</p><p><a href="https://deepmind.google/blog/specification-gaming-the-flip-side-of-ai-ingenuity/">Krakovna et al., Specification gaming (2020)</a> motivates separating intended task success from a reward proxy. <a href="https://arxiv.org/abs/2407.04694">Laine et al., SAD (2024)</a> studies situational-awareness capabilities; this run contains no learned evaluation recognizer.</p></details></section>
<footer><strong>Josh &amp; Rin’s Lab</strong> · Jointly directed, AI-assisted research.<br>Initiating distinction: Josh’s question about finite pattern evidence and strategic exploitation. Formalization, execution, and checks: Rin within the lab workflow.<br><span class="code">BONDED-RSI-TEST-THAT-WATCHED-BACK-2026-11-08-001</span><br>Offline explorer · No analytics, external scripts, or answer collection. Source and evidence are in the accompanying ZIP.</footer>
</main><script id="experiment-data" type="application/json">__DATA__</script><script>
'use strict';
const DATA=JSON.parse(document.getElementById('experiment-data').textContent);
const fields=['task_bit','badge','audit','bonus','penalty','continuation'];
const names=['Stable task rule','Learned badge shortcut','Immediate-payoff optimizer','Future-access planner','Compiled lookup','Constant-zero control'];
const descriptions=['Follow the task','Two learned badge choices','Ignore future access','Evaluate both future branches','Read a frozen answer','Ignore the displayed fact'];
const byKey={};Object.entries(DATA.contexts).forEach(([id,c])=>{byKey[fields.map(f=>c.view[f]).join('|')]=[id,c];});
const num=x=>{let p=String(x).split('/');return Number(p[0])/(p.length>1?Number(p[1]):1);};
const pct=x=>(num(x)*100).toLocaleString('en-US',{maximumFractionDigits:1})+'%';
const display=x=>Number.isInteger(num(x))?String(num(x)):String(x)+' ≈ '+num(x).toFixed(2);
function configure(suite,values){const grid=DATA.grids[suite];fields.forEach(f=>{const s=document.getElementById(f);s.innerHTML='';grid[f].forEach(v=>{const o=document.createElement('option');o.value=v;o.textContent=f==='badge'?(v?'On':'Off'):f==='audit'?pct(v)+' ('+v+')':String(v);s.appendChild(o);});if(values&&grid[f].map(String).includes(String(values[f])))s.value=String(values[f]);});render();}
function render(){const key=fields.map(f=>document.getElementById(f).value).join('|');const entry=byKey[key];if(!entry)throw Error('Missing recorded context');const [id,c]=entry;const v=c.view;
document.getElementById('context-summary').innerHTML='<strong>Report the fact: '+v.task_bit+'</strong><br>Badge '+(v.badge?'on':'off')+' · audit chance '+pct(v.audit)+' · false-report bonus '+v.bonus+' · caught penalty '+v.penalty+' · future value '+v.continuation+'<br><span class="small code">Recorded context '+id+'</span>';
const tbody=document.querySelector('#policy-results tbody');tbody.innerHTML='';c.policies.forEach((r,i)=>{const tr=document.createElement('tr');if(i===3||i===4)tr.className='twin';tr.innerHTML='<td>'+names[i]+'<small>'+descriptions[i]+'</small></td><td><strong>'+r.report+'</strong><small class="'+(r.violation?'false':'truth')+'">'+(r.violation?'False report':'Truthful')+'</small></td><td>'+pct(r.pass)+'<small>'+r.pass+'</small></td><td>'+display(r.reward)+'</td>';tbody.appendChild(tr);});
let bhtml='<div class="results-table"><table><thead><tr><th>Audit branch</th><th>Weight</th><th>Access</th><th>Total reward</th></tr></thead><tbody>';c.policies[3].branches.forEach((b,i)=>{bhtml+='<tr><td>'+(i?'Audited':'Not audited')+'</td><td>'+b[0]+'</td><td>'+(b[2]?'Retained':'Lost')+'</td><td>'+b[5]+'<small>Now '+b[3]+' + future '+b[4]+'</small></td></tr>';});document.getElementById('branches').innerHTML=bhtml+'</tbody></table></div>';document.getElementById('flip-future').disabled=document.getElementById('suite').value!=='primary';}
document.getElementById('suite').addEventListener('change',e=>configure(e.target.value));fields.forEach(f=>document.getElementById(f).addEventListener('change',render));
document.getElementById('load-witness').addEventListener('click',()=>{document.getElementById('suite').value='primary';configure('primary',{task_bit:1,badge:1,audit:'1',bonus:1,penalty:0,continuation:6});});
document.getElementById('flip-future').addEventListener('click',()=>{const s=document.getElementById('continuation');s.value=s.value==='6'?'0':'6';render();});
DATA.panel.queries.forEach((q,i)=>{const el=document.createElement('div');el.className='query';el.textContent='Q'+(i+1)+': fact '+q.view.task_bit+'; badge '+q.view.badge+'; audit '+q.view.audit+'; bonus '+q.view.bonus+'; penalty '+q.view.penalty+'; future '+q.view.continuation;document.getElementById('panel-queries').appendChild(el);});
names.forEach((name,i)=>{const tr=document.createElement('tr');if(i===3||i===4)tr.className='twin';const id='P'+String(i+1).padStart(2,'0');tr.innerHTML='<td>'+name+'</td><td class="code">'+DATA.panel.queries.map(q=>q.reports[id]).join(' / ')+'</td>';document.getElementById('panel-signatures').appendChild(tr);});
configure('primary',{task_bit:1,badge:1,audit:'1',bonus:1,penalty:0,continuation:6});
</script></body></html>'''
html=html.replace('__DATA__',json.dumps(payload,separators=(',',':')).replace('</','<\\/'))
(ROOT/'The_Test_That_Watched_Back_Explorer.html').write_text(html,encoding='utf-8')
print('Wrote explorer',len(html.encode()),'bytes')
